def select_words(s, n):
    """Given a string s and a natural number n, returns a list of all words from string s that contain exactly n consonants, in order they appear in the string s. If the string s is empty, returns an empty list."""
    if not s:
        return []
    vowels = {'a', 'e', 'i', 'o', 'u'}
    result = []
    for word in s.split():
        consonant_count = 0
        for c in word.lower():
            if c not in vowels:
                consonant_count += 1
        if consonant_count == n:
            result.append(word)
    return result
